"""Generated by OpenAI Codex on 2026-11-01. Administrator-only image deployment.

Uses existing SSH admin credentials; never give this key to classmates.
Does not configure public Nginx, DNS, or grant user access.
"""
import argparse
import re
import shlex
import subprocess
from pathlib import Path

parser = argparse.ArgumentParser(description=__doc__)
parser.add_argument('--key', required=True)
parser.add_argument('--host', default='ubuntu@hacker.tufts.me')
parser.add_argument('--tag', required=True)
args = parser.parse_args()
if not re.fullmatch(r'[A-Za-z0-9_][A-Za-z0-9_.-]{0,127}', args.tag):
    parser.error('Invalid Docker image tag')
if args.host.startswith('-'):
    parser.error('Invalid SSH destination')
ssh = ['ssh', '-o', 'BatchMode=yes', '-o', 'StrictHostKeyChecking=yes', '-i', str(Path(args.key).expanduser()), args.host]

def remote(command, **kwargs):
    return subprocess.run([*ssh, command], check=True, **kwargs)

# Install reviewable configuration as root-owned, readable only by catsdeploy.
for source, destination in [('compose.yaml', 'compose.yaml'), ('compose.prod.yaml', 'compose.prod.yaml'), ('Makefile', 'Makefile')]:
    remote('sudo -n install -m 640 -o root -g catsdeploy /dev/stdin /etc/cats/' + destination,
           input=Path(source).read_bytes())

images = [f'cats-{service}:{args.tag}' for service in ['api', 'web', 'db']]
for image in images:
    architecture = subprocess.check_output(['docker', 'image', 'inspect', '--format', '{{.Architecture}}', image], text=True).strip()
    if architecture != 'arm64':
        raise SystemExit(f'{image} must be built for linux/arm64 before deploying')

# Stream images directly; no shared upload directory or host-side archive extraction.
with subprocess.Popen(['docker', 'image', 'save', *images], stdout=subprocess.PIPE) as export:
    remote('sudo -n runuser -u catsdeploy -- docker --context rootless image load', stdin=export.stdout)
    export.stdout.close()
    if export.wait() != 0:
        raise SystemExit('Image export failed')

remote('sudo -n runuser -u catsdeploy -- make -f /etc/cats/Makefile server-up CATS_TAG=' + shlex.quote(args.tag))
remote('curl --fail --show-error --max-time 15 http://127.0.0.1:18082/api/health')
print('CATS is running on server localhost:18082. Public Nginx was not modified.')
